package dao; import java.sql.*; import negocio.PreferenciasComunidad; public class PreferenciasComunidadDAOMySQL implements PreferenciasComunidadDAO { public PreferenciasComunidad buscar(Connection c,long id){try(PreparedStatement s=c.prepareStatement("SELECT cliente_id,buscar_turnos,buscar_torneos,contacto_whatsapp,fecha_consentimiento_whatsapp,fecha_actualizacion,version FROM comunidad_preferencias WHERE cliente_id=?")){s.setLong(1,id);try(ResultSet r=s.executeQuery()){if(!r.next())return null;PreferenciasComunidad p=new PreferenciasComunidad();p.setClienteId(r.getLong(1));p.setBuscarTurnos(r.getBoolean(2));p.setBuscarTorneos(r.getBoolean(3));p.setContactoWhatsapp(r.getBoolean(4));Timestamp t=r.getTimestamp(5);if(t!=null)p.setFechaConsentimientoWhatsapp(t.toLocalDateTime());t=r.getTimestamp(6);if(t!=null)p.setFechaActualizacion(t.toLocalDateTime());p.setVersion(r.getLong(7));return p;}}catch(SQLException e){throw new RuntimeException("No se pudieron consultar las preferencias de Comunidad.",e);}} public void guardar(Connection c,PreferenciasComunidad p){p.validar();String q="INSERT INTO comunidad_preferencias(cliente_id,buscar_turnos,buscar_torneos,contacto_whatsapp,fecha_consentimiento_whatsapp,version) VALUES(?,?,?,?,?,0) ON DUPLICATE KEY UPDATE buscar_turnos=VALUES(buscar_turnos),buscar_torneos=VALUES(buscar_torneos),contacto_whatsapp=VALUES(contacto_whatsapp),fecha_consentimiento_whatsapp=VALUES(fecha_consentimiento_whatsapp),version=version+1";try(PreparedStatement s=c.prepareStatement(q)){s.setLong(1,p.getClienteId());s.setBoolean(2,p.isBuscarTurnos());s.setBoolean(3,p.isBuscarTorneos());s.setBoolean(4,p.isContactoWhatsapp());if(p.getFechaConsentimientoWhatsapp()==null)s.setNull(5,Types.TIMESTAMP);else s.setTimestamp(5,Timestamp.valueOf(p.getFechaConsentimientoWhatsapp()));s.executeUpdate();}catch(SQLException e){throw new RuntimeException("No se pudieron guardar las preferencias de Comunidad.",e);}}}